var ORDBOK = {"pl":{"ByggLogg":"ByggLogg","Funksjoner":"Funkcje","Se appen":"Zobacz aplikację","Tjenester":"Usługi","Pris":"Cena","Kontakt":"Kontakt","For byggefirma og håndverkere":"Dla firm budowlanych i fachowców","Hele byggeplassen":"Cała budowa","i lomma.":"w kieszeni.","ByggLogg samler stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat i én app på telefonen. Prosjektene kommer rett fra Visma Business NXT eller Tripletex, og lønnsgrunnlaget er klart når måneden er slutt.":"ByggLogg łączy odbijanie wejścia i wyjścia, godziny pracy, plan pracy, materiały, kontrolę własną, reklamacje, urlopy i czat w jednej aplikacji na telefonie. Projekty trafiają prosto z Visma Business NXT lub Tripletex, a dane do wypłaty są gotowe zaraz po zakończeniu miesiąca.","Prøv demoen →":"Wypróbuj demo →","Snakk med oss":"Porozmawiaj z nami","Norsk, polsk, engelsk og litauisk":"Norweski, polski, angielski i litewski","Ingen app-butikk":"Bez sklepu z aplikacjami","Data lagret i EU":"Dane przechowywane w UE","Hva ByggLogg gjør":"Co robi ByggLogg","Laget på en byggevarehandel. Brukt hver dag av snekkerne.":"Stworzona w hurtowni budowlanej. Używana codziennie przez cieśli.","ByggLogg er utviklet ute i bransjen, sammen med snekkere som bruker appen hver dag, for å bli kvitt lapper, SMS-er og regneark. Alt de ansatte trenger på jobb ligger i én app, og leder får oversikten uten å ringe rundt.":"ByggLogg powstał w branży, razem z cieślami, którzy codziennie korzystają z aplikacji – po to, by pozbyć się karteczek, SMS-ów i arkuszy kalkulacyjnych. Wszystko, czego pracownicy potrzebują w pracy, jest w jednej aplikacji, a kierownik ma pełny obraz sytuacji bez obdzwaniania wszystkich.","Stempling og timer":"Odbijanie i godziny pracy","Logg inn og ut med ett trykk, på riktig prosjekt. Dagen vises som et målebånd, så hullene synes.":"Zaloguj wejście i wyjście jednym dotknięciem, na właściwy projekt. Dzień wyświetla się jak miarka, więc od razu widać luki.","Virker uten nett – sendes når dekningen er tilbake":"Działa bez internetu – dane wysyłają się, gdy wróci zasięg","Nyhet":"Nowość","Varsel hvis noen har glemt å logge ut":"Powiadomienie, gdy ktoś zapomni się wylogować","Overtid, lunsj og kjøring regnes ut":"Nadgodziny, przerwa na lunch i dojazdy liczone automatycznie","Lønnsgrunnlag rett til lønnssystemet":"Dane do wypłaty prosto do systemu płacowego","Prosjekter":"Projekty","Adresse med kart, kontaktperson, selger, snekker og timer brukt mot kalkyle på hvert prosjekt.":"Adres z mapą, osoba kontaktowa, sprzedawca, cieśla i godziny zużyte w porównaniu z kosztorysem – dla każdego projektu.","Hentes fra Visma eller Tripletex":"Pobierane z Visma lub Tripletex","Søk på nummer, kunde eller adresse":"Szukaj po numerze, kliencie lub adresie","Slå sammen to prosjekter som er samme jobb":"Połącz dwa projekty, które dotyczą tej samej pracy","Arbeidsplan":"Plan pracy","Leder deler ut jobber med dato til de ansatte. Ukeplanen viser hvem som er hvor, og hvem som har ferie.":"Kierownik przydziela pracownikom zadania z datą. Plan tygodnia pokazuje, kto jest gdzie i kto ma urlop.","Trykk på en dag for å planlegge":"Dotknij dnia, aby go zaplanować","Bare hverdager – helg når det trengs":"Tylko dni robocze – weekend, gdy jest potrzebny","«Mitt arbeid» for hver ansatt":"„Moja praca” dla każdego pracownika","Push-varsel når du får ny jobb":"Powiadomienie push, gdy dostajesz nowe zadanie","Materiell og bestilling":"Materiały i zamówienia","Materiallisten deles i leveranser i riktig rekkefølge. Snekkeren bestiller fra byggeplassen, og butikken plukker.":"Lista materiałów jest dzielona na dostawy we właściwej kolejności. Cieśla zamawia prosto z budowy, a sklep kompletuje towar.","Leveranser med dato og status":"Dostawy z datą i statusem","Bestilling rett til butikk og lager":"Zamówienie prosto do sklepu i magazynu","Huk av det som er levert":"Odhacz to, co zostało dostarczone","Egenkontroll og HMS":"Kontrola własna i BHP","Sjekklister for våtrom, tetting, vinduer og brann som signeres på stedet, og sikker jobbanalyse før risikoarbeid.":"Listy kontrolne dla łazienek, uszczelnień, okien i ochrony przeciwpożarowej podpisywane na miejscu oraz analiza bezpieczeństwa pracy (SJA) przed pracami ryzykownymi.","SJA som alle kvitterer på":"SJA potwierdzana przez wszystkich","Mannskapsliste med HMS-kort":"Lista ekipy z kartami HMS-kort","Avvik og uønskede hendelser":"Odstępstwa i zdarzenia niepożądane","Dokumentasjon":"Dokumentacja","Dagbok, bilder og tilleggsarbeid lagres på prosjektet mens jobben pågår. Kunden signerer tillegg på telefonen.":"Dziennik budowy, zdjęcia i prace dodatkowe zapisują się w projekcie na bieżąco. Klient podpisuje prace dodatkowe na telefonie.","Sluttrapport og FDV til kunden":"Raport końcowy i FDV dla klienta","Klar for Boligmappa":"Gotowe do Boligmappa","Vær fra Meteorologisk institutt":"Pogoda z Norweskiego Instytutu Meteorologicznego","Serviceoppdrag":"Zlecenia serwisowe","Små betalte jobber hos kunden som gjøres på en dag eller to. Merk hva som haster, del ut til en snekker og fakturer når det er gjort.":"Małe płatne prace u klienta, wykonywane w dzień lub dwa. Oznacz, co jest pilne, przydziel cieśli i wystaw fakturę po wykonaniu.","Haster, denne uken eller når det passer":"Pilne, w tym tygodniu lub w dogodnym terminie","Kunden bestiller selv via skjema på nettsiden":"Klient sam zamawia przez formularz na stronie","Timer og materiell rett til «Klar til fakturering»":"Godziny i materiały prosto do „Gotowe do fakturowania”","Kunden kvitterer på telefonen":"Klient potwierdza na telefonie","Fire språk":"Cztery języki","Hver ansatt bruker appen på sitt eget språk: norsk, polsk, engelsk eller litauisk. Prosjekter, timer og chat er de samme for alle – det er bare knapper og tekster som byttes.":"Każdy pracownik korzysta z aplikacji we własnym języku: norweskim, polskim, angielskim lub litewskim. Projekty, godziny i czat są wspólne dla wszystkich – zmieniają się tylko przyciski i teksty.","Velg språk allerede på innloggingen":"Wybór języka już przy logowaniu","Invitasjonen kommer på den ansattes språk":"Zaproszenie w języku pracownika","Veiledning for iPhone og Android på alle språk":"Instrukcja dla iPhone’a i Androida we wszystkich językach","Reklamasjon":"Reklamacje","Når kunden melder feil på en ferdig jobb, registreres det på jobben med bilder. Leder vurderer, og utbedringen planlegges.":"Gdy klient zgłasza usterkę w zakończonej pracy, rejestruje się ją przy tej pracy wraz ze zdjęciami. Kierownik ocenia sprawę i planuje naprawę.","Timer på reklamasjon faktureres ikke":"Godziny przy reklamacji nie są fakturowane","Kunden kvitterer når det er rettet":"Klient potwierdza po usunięciu usterki","Hva reklamasjoner koster i året":"Ile kosztują reklamacje w skali roku","Tilleggsarbeid":"Prace dodatkowe","Råteskade eller ekstraarbeid som dukker opp underveis blir et eget underprosjekt på jobben. Timene føres på tillegget, så du ser forbruket mot anslaget.":"Zgnilizna czy dodatkowe prace, które wychodzą w trakcie, stają się osobnym podprojektem w ramach zlecenia. Godziny wpisuje się na prace dodatkowe, więc widać zużycie w porównaniu z szacunkiem.","Kunden signerer på telefonen":"Klient podpisuje na telefonie","Snekkeren velger «Gjelder: tillegg» når han fører timer":"Cieśla przy wpisywaniu godzin wybiera „Dotyczy: prace dodatkowe”","Faktureres for seg, også på fastprisjobber":"Fakturowane osobno, także przy pracach za stałą cenę","Månedsrapport per ansatt":"Raport miesięczny dla każdego pracownika","Hver ansatt får sin egen rapport. Snekkerne ser timer på kunde mot interntid, og butikk og prosjektleder ser dekningsgrad på salget sitt.":"Każdy pracownik dostaje własny raport. Cieśle widzą godziny u klienta w porównaniu z czasem wewnętrznym, a sklep i kierownik projektu widzą marżę na swojej sprzedaży.","Sammenlignet med forrige måned og snittet":"W porównaniu z poprzednim miesiącem i średnią","DG per varegruppe rett fra regnskapet":"Marża według grup towarowych prosto z księgowości","Push-varsel når rapporten er klar":"Powiadomienie push, gdy raport jest gotowy","Salg per avdeling":"Sprzedaż według działów","Egen rapport for hver avdeling, for eksempel kjøkken og interiør: antall salg, omsetning, dekningsbidrag og DG, hentet rett fra Visma.":"Osobny raport dla każdego działu, np. kuchnie i wnętrza: liczba sprzedaży, obrót, zysk brutto i marża, pobierane prosto z Visma.","Per måned og hittil i år mot i fjor":"Za miesiąc i od początku roku, w porównaniu z ubiegłym rokiem","Ordre uten innkjøpspris vises for seg":"Zamówienia bez ceny zakupu pokazywane osobno","Avdelingen ser sin egen rapport":"Dział widzi własny raport","Egen logo og farger":"Własne logo i kolory","Last opp logoen, så finner appen fargene i den og lager firmafarger. ByggLogg-merket står ved siden av.":"Wgraj logo, a aplikacja znajdzie w nim kolory i stworzy z nich kolory firmowe. Obok widnieje znak ByggLogg.","Logo øverst i appen":"Logo na górze aplikacji","Logo og farger på sluttrapporten til kunden":"Logo i kolory w raporcie końcowym dla klienta","Hver ansatt kan velge egne farger":"Każdy pracownik może wybrać własne kolory","Ferie og fravær":"Urlopy i nieobecności","Søk ferie i appen og se felles feriekalender. Leder godkjenner med ett trykk.":"Wnioskuj o urlop w aplikacji i przeglądaj wspólny kalendarz urlopów. Kierownik zatwierdza jednym dotknięciem.","Feriedager etter ferieloven":"Dni urlopu zgodnie z norweską ustawą urlopową (ferieloven)","Egenmelding og sykt barn":"Zwolnienie na własne oświadczenie (egenmelding) i opieka nad chorym dzieckiem","Kalender til mobilen":"Kalendarz w telefonie","Chat og varsler":"Czat i powiadomienia","Felles chat, egen tråd per prosjekt og private meldinger, med push-varsel på telefonen.":"Wspólny czat, osobny wątek dla każdego projektu i wiadomości prywatne, z powiadomieniami push na telefonie.","Bilder rett i chatten":"Zdjęcia prosto w czacie","Varsel om nye prosjekter og bestillinger":"Powiadomienia o nowych projektach i zamówieniach","Hele appen på norsk, polsk, engelsk og litauisk":"Cała aplikacja po norwesku, polsku, angielsku i litewsku","Raskt i gang":"Szybki start","Godkjenn ByggLogg i Visma, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Ansatte fra regnskapet legges til med ett trykk.":"Zatwierdź ByggLogg w Visma albo wklej klucz z Tripletex, a firma połączy się sama. Pracowników z księgowości dodasz jednym dotknięciem.","Invitasjon på e-post på den ansattes eget språk":"Zaproszenie e-mailem we własnym języku pracownika","Egen veiledning for iPhone og Android":"Osobna instrukcja dla iPhone’a i Androida","«Kom i gang»-liste som viser hva som gjenstår":"Lista „Pierwsze kroki” pokazująca, co zostało do zrobienia","Slik ser det ut":"Tak to wygląda","Bygget for telefonen. Like god på PC.":"Stworzona na telefon. Równie dobra na komputerze.","Snekkerne bruker ByggLogg på telefonen ute. Leder og butikk har den samme appen på PC, med ukeplan, bestillinger og reklamasjoner på én side.":"Cieśle używają ByggLogg na telefonie w terenie. Kierownik i sklep mają tę samą aplikację na komputerze – z planem tygodnia, zamówieniami i reklamacjami na jednej stronie.","Arbeidsplan.":"Plan pracy.","Hele uka for alle ansatte. Trykk på en ledig dag for å dele ut en jobb.":"Cały tydzień dla wszystkich pracowników. Dotknij wolnego dnia, aby przydzielić zadanie.","Butikk og prosjektleder.":"Sklep i kierownik projektu.","Bestillinger fra byggeplassen og reklamasjoner som skal følges opp.":"Zamówienia z budowy i reklamacje do załatwienia.","Alt om jobben på ett sted.":"Wszystko o zleceniu w jednym miejscu.","Plan, materiell, egenkontroll, bilder, avvik og sluttdokumentasjon på prosjektet.":"Plan, materiały, kontrola własna, zdjęcia, odstępstwa i dokumentacja końcowa w projekcie.","Regnskap og lønn":"Księgowość i płace","Ingen dobbeltføring":"Bez podwójnego wpisywania","ByggLogg henter prosjekter og kunder automatisk fra regnskapssystemet dere allerede bruker. Det de ansatte registrerer ute, går tilbake som grunnlag for faktura og lønn.":"ByggLogg automatycznie pobiera projekty i klientów z systemu księgowego, którego już używacie. To, co pracownicy rejestrują w terenie, wraca jako podstawa do faktur i wypłat.","Visma Business NXT":"Visma Business NXT","Prosjekter, kunder, materiell og fakturerte timer":"Projekty, klienci, materiały i zafakturowane godziny","Tripletex":"Tripletex","Prosjekter, kunder og ansatte inn, godkjente timer og lønnsgrunnlag ut":"Na wejściu projekty, klienci i pracownicy, na wyjściu zatwierdzone godziny i dane do wypłaty","Visma Lønn":"Visma Lønn","Timer, overtid, kjøring, ferie og fravær som importfil":"Godziny, nadgodziny, dojazdy, urlopy i nieobecności jako plik importu","Prosjektet opprettes":"Projekt zostaje utworzony","Kontoret lager ordren i Visma, eller snekkeren oppretter prosjektet i appen når jobben starter før papirene er klare.":"Biuro zakłada zlecenie w Visma albo cieśla tworzy projekt w aplikacji, gdy praca rusza, zanim papiery są gotowe.","Jobben gjøres":"Praca jest wykonywana","Timer, bilder, avvik og materiell registreres på prosjektet. Prosjekter laget i appen kobles til prosjektet i regnskapet når det kommer.":"Godziny, zdjęcia, odstępstwa i materiały rejestruje się w projekcie. Projekty utworzone w aplikacji łączą się z projektem w księgowości, gdy ten się pojawi.","Grunnlaget er klart":"Dane są gotowe","Leder ser timer klare til fakturering, og sender lønnsgrunnlaget for måneden rett til Tripletex eller Visma Lønn – på bedriftens egne lønnsarter, uten å skrive noe av på nytt.":"Kierownik widzi godziny gotowe do fakturowania i wysyła dane do wypłaty za dany miesiąc prosto do Tripletex lub Visma Lønn – według własnych składników płacowych firmy, bez przepisywania czegokolwiek.","Vi setter det opp for dere":"Skonfigurujemy to za was","Dere skal ikke trenge en IT-avdeling for å komme i gang. Vi gjør jobben, og dere får én person å ringe.":"Nie potrzebujecie działu IT, żeby zacząć. My wykonujemy pracę, a wy macie jedną osobę do kontaktu.","Oppsett og import":"Konfiguracja i import","Vi legger inn ansatte, satser, regler for overtid og tillegg, og importerer prosjekter og kunder.":"Wprowadzamy pracowników, stawki, zasady nadgodzin i dodatków oraz importujemy projekty i klientów.","Kobling til regnskap":"Połączenie z księgowością","Godkjenn ByggLogg i Visma Business NXT, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Prosjekter, kunder og ansatte hentes inn, og timene går rett til lønn.":"Zatwierdź ByggLogg w Visma Business NXT albo wklej klucz z Tripletex, a firma połączy się sama. Projekty, klienci i pracownicy zostaną pobrani, a godziny trafią prosto do płac.","Opplæring og invitasjon":"Szkolenie i zaproszenia","De ansatte får invitasjon på e-post med innlogging og hvordan appen lagres på iPhone og Android. Kort gjennomgang på morgenmøtet, og en «Kom i gang»-liste for leder.":"Pracownicy dostają zaproszenie e-mailem z danymi logowania i instrukcją, jak zapisać aplikację na iPhonie i Androidzie. Krótkie omówienie na porannej odprawie i lista „Pierwsze kroki” dla kierownika.","Egen profil":"Własny profil","Firmanavn og logo i appen, i rapportene og i sluttdokumentasjonen dere sender kunden.":"Nazwa firmy i logo w aplikacji, w raportach i w dokumentacji końcowej, którą wysyłacie klientowi.","Brukerstøtte":"Wsparcie techniczne","Svar på norsk fra folk som kjenner byggebransjen. Feil rettes fortløpende.":"Odpowiedzi po norwesku od ludzi, którzy znają branżę budowlaną. Błędy naprawiamy na bieżąco.","Videreutvikling":"Dalszy rozwój","Nye funksjoner kommer jevnlig, og mange av dem starter som ønsker fra kundene.":"Nowe funkcje pojawiają się regularnie, a wiele z nich zaczyna się od życzeń klientów.","Tilpass ByggLogg":"Dopasuj ByggLogg","Satt opp etter hvordan dere jobber":"Ustawione tak, jak pracujecie","Hver bedrift er forskjellig. Det meste stilles inn av leder i appen, og resten hjelper vi dere med.":"Każda firma jest inna. Większość ustawia kierownik w aplikacji, a w reszcie wam pomożemy.","Tilpasses per bedrift":"Dopasowanie do każdej firmy","Firmanavn, logo og farger i appen og i dokumentene til kunden":"Nazwa firmy, logo i kolory w aplikacji i w dokumentach dla klienta","Avdelinger og hvor mange som kan ha ferie samtidig":"Działy i ile osób może mieć jednocześnie urlop","Normaltid, lunsjtrekk og overtid per ansatt":"Normalny czas pracy, potrącenie za lunch i nadgodziny dla każdego pracownika","Feriedager etter avtale, med ekstra uke over 60 år":"Dni urlopu według umowy, z dodatkowym tygodniem powyżej 60. roku życia","Varsel når noen har glemt å stemple ut, med egen grense per ansatt":"Powiadomienie, gdy ktoś zapomni odbić wyjście, z indywidualnym limitem dla każdego pracownika","Kvoter for arbeidstøy, verktøy og verneutstyr":"Limity na odzież roboczą, narzędzia i środki ochrony","Slå av deler av appen dere ikke bruker":"Wyłącz części aplikacji, których nie używacie","Oversikt for leder: fakturerte timer mot mål, lønnsomhet, kurs og utstyr":"Przegląd dla kierownika: zafakturowane godziny w porównaniu z celem, rentowność, kursy i sprzęt","Prosjektleder-rolle for butikk og kontor":"Rola kierownika projektu dla sklepu i biura","Personlig månedsrapport til hver ansatt, med det som er viktig i jobben deres":"Osobisty raport miesięczny dla każdego pracownika, z tym, co ważne w jego pracy","Salgsrapport per avdeling, synlig for avdelingen selv":"Raport sprzedaży według działów, widoczny dla samego działu","Fast serviceprosjekt og eget bestillingsskjema for kundene":"Stały projekt serwisowy i własny formularz zamówień dla klientów","Kampanjer fra kjeden på startsiden":"Promocje sieci na stronie startowej","Språk for hver ansatt: norsk, polsk, engelsk eller litauisk":"Język dla każdego pracownika: norweski, polski, angielski lub litewski","Andre koblinger":"Inne integracje","Kart og kjøreavstand til prosjektet fra Kartverket":"Mapa i odległość dojazdu do projektu z Kartverket","Sluttdokumentasjon og FDV klar for Boligmappa":"Dokumentacja końcowa i FDV gotowe do Boligmappa","Ferie og fravær rett i kalenderen på mobilen":"Urlopy i nieobecności prosto w kalendarzu w telefonie","Værmelding fra Meteorologisk institutt":"Prognoza pogody z Norweskiego Instytutu Meteorologicznego","Push-varsler for chat, nye prosjekter, ny jobb, bestillinger, serviceoppdrag og månedsrapporten":"Powiadomienia push o czacie, nowych projektach, nowych zadaniach, zamówieniach, zleceniach serwisowych i raporcie miesięcznym","Invitasjon på e-post med egen veiledning for iPhone og Android":"Zaproszenie e-mailem z osobną instrukcją dla iPhone’a i Androida","Import av timer fra Svenn ved bytte av system":"Import godzin z Svenn przy zmianie systemu","Trenger dere en kobling vi ikke har? Si fra. Mange av funksjonene i ByggLogg startet som ønsker fra kundene.":"Potrzebujecie integracji, której nie mamy? Dajcie znać. Wiele funkcji w ByggLogg zaczęło się od życzeń klientów.","Én pris per bruker":"Jedna cena za użytkownika","Dere betaler for de ansatte som bruker appen, måned for måned. Alle funksjoner er med.":"Płacicie za pracowników, którzy korzystają z aplikacji, miesiąc po miesiącu. Wszystkie funkcje w cenie.","kr per bruker / mnd":"kr za użytkownika / mies.","eks. mva. · minst 5 brukere":"bez VAT · minimum 5 użytkowników","Tillegg: kobling til Visma Business NXT eller Tripletex":"Dodatkowo: integracja z Visma Business NXT lub Tripletex","kr per bedrift / mnd":"kr za firmę / mies.","eks. mva. · 2 500 kr i oppstart":"bez VAT · 2 500 kr opłaty startowej","Alle funksjoner":"Wszystkie funkcje","Nye versjoner":"Nowe wersje","Personvern og sikkerhet":"Prywatność i bezpieczeństwo","Trygt for de ansatte":"Bezpieczne dla pracowników","ByggLogg følger personvernforordningen (GDPR) og arbeidsmiljølovens krav til oversikt over arbeidstid. Vi inngår databehandleravtale med alle kunder.":"ByggLogg przestrzega ogólnego rozporządzenia o ochronie danych (RODO) oraz wymogów norweskiej ustawy o środowisku pracy (arbeidsmiljøloven) dotyczących ewidencji czasu pracy. Z każdym klientem zawieramy umowę powierzenia przetwarzania danych.","Les avtalevilkårene":"Przeczytaj warunki umowy","Lagring":"Przechowywanie","Alle opplysninger lagres i EU (Irland).":"Wszystkie dane są przechowywane w UE (Irlandia).","Posisjon":"Lokalizacja","Appen sporer ikke hvor de ansatte er.":"Aplikacja nie śledzi, gdzie są pracownicy.","Sykefravær":"Zwolnienia chorobowe","Bare typen fravær registreres, aldri diagnose.":"Rejestrowany jest tylko rodzaj nieobecności, nigdy diagnoza.","Uten nett":"Bez internetu","Det som er hentet, ligger på telefonen til den ansatte logger ut.":"To, co zostało pobrane, zostaje na telefonie, dopóki pracownik się nie wyloguje.","Innlogging":"Logowanie","Engangskode på e-post. Ingen passord å glemme.":"Jednorazowy kod e-mailem. Żadnych haseł do zapamiętania.","Tilgang":"Dostęp","Ansatte ser sine egne tall. Private meldinger kan bare leses av de to som skriver.":"Pracownicy widzą własne dane. Wiadomości prywatne mogą czytać tylko dwie osoby, które je piszą.","Kom i gang":"Zacznij","Se ByggLogg i bruk":"Zobacz ByggLogg w działaniu","Prøv demoen selv, eller ta kontakt for en gjennomgang. Vi viser gjerne hvordan appen brukes på en vanlig arbeidsdag.":"Wypróbuj demo samodzielnie albo skontaktuj się z nami, by umówić prezentację. Chętnie pokażemy, jak aplikacja działa w zwykły dzień pracy.","Ståle Jonassen":"Ståle Jonassen","Jonassen AS":"Jonassen AS","Lepsøyvegen 210, 6292 Kjerstad":"Lepsøyvegen 210, 6292 Kjerstad","post@bygglogg.app":"post@bygglogg.app","Kopier e-postadresse":"Kopiuj adres e-mail","ByggLogg er et varemerke fra Jonassen AS · Lepsøyvegen 210, 6292 Kjerstad · org.nr. 919 665 319":"ByggLogg jest znakiem towarowym Jonassen AS · Lepsøyvegen 210, 6292 Kjerstad · nr org. 919 665 319","Avtalevilkår":"Warunki umowy","Personvern":"Prywatność","Hovedmeny":"Menu główne","Skjermbilde av ByggLogg på telefon":"Zrzut ekranu ByggLogg na telefonie","Forsiden i ByggLogg: snekkeren er logget inn på prosjektet Skifte vindu og ser timene sine for dagen":"Ekran główny ByggLogg: cieśla jest zalogowany do projektu „Wymiana okna” i widzi swoje dzisiejsze godziny","Ukeplanen i ByggLogg med jobber fordelt på de ansatte":"Plan tygodnia w ByggLogg z zadaniami rozdzielonymi między pracowników","Bestillinger fra byggeplassen og reklamasjoner i ByggLogg":"Zamówienia z budowy i reklamacje w ByggLogg","Delene av et prosjekt i ByggLogg: plan, materiell, egenkontroll, SJA, chat, dagbok og mer":"Części projektu w ByggLogg: plan, materiały, kontrola własna, SJA, czat, dziennik i więcej","ByggLogg er appen for byggefirma: stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat – koblet til Visma Business NXT og Tripletex.":"ByggLogg to aplikacja dla firm budowlanych: odbijanie czasu pracy, godziny, plan pracy, materiały, kontrola własna, reklamacje, urlopy i czat – zintegrowana z Visma Business NXT i Tripletex.","Kopiert":"Skopiowano","Merket – trykk Kopier":"Zaznaczono – naciśnij Kopiuj"},"en":{"ByggLogg":"ByggLogg","Funksjoner":"Features","Se appen":"See the app","Tjenester":"Services","Pris":"Pricing","Kontakt":"Contact","For byggefirma og håndverkere":"For construction firms and tradespeople","Hele byggeplassen":"The whole building site","i lomma.":"in your pocket.","ByggLogg samler stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat i én app på telefonen. Prosjektene kommer rett fra Visma Business NXT eller Tripletex, og lønnsgrunnlaget er klart når måneden er slutt.":"ByggLogg brings clocking in, hours, work plan, materials, quality control, warranty claims, holiday and chat together in one app on your phone. Projects come straight from Visma Business NXT or Tripletex, and payroll data is ready when the month ends.","Prøv demoen →":"Try the demo →","Snakk med oss":"Talk to us","Norsk, polsk, engelsk og litauisk":"Norwegian, Polish, English and Lithuanian","Ingen app-butikk":"No app store","Data lagret i EU":"Data stored in the EU","Hva ByggLogg gjør":"What ByggLogg does","Laget på en byggevarehandel. Brukt hver dag av snekkerne.":"Made at a builders’ merchant. Used every day by the carpenters.","ByggLogg er utviklet ute i bransjen, sammen med snekkere som bruker appen hver dag, for å bli kvitt lapper, SMS-er og regneark. Alt de ansatte trenger på jobb ligger i én app, og leder får oversikten uten å ringe rundt.":"ByggLogg was developed out in the trade, together with carpenters who use the app every day, to get rid of notes, text messages and spreadsheets. Everything employees need at work is in one app, and managers get the overview without calling around.","Stempling og timer":"Clocking in and hours","Logg inn og ut med ett trykk, på riktig prosjekt. Dagen vises som et målebånd, så hullene synes.":"Clock in and out with one tap, on the right project. The day is shown as a tape measure, so the gaps stand out.","Virker uten nett – sendes når dekningen er tilbake":"Works offline – syncs when you’re back in coverage","Nyhet":"New","Varsel hvis noen har glemt å logge ut":"Alert if someone forgot to clock out","Overtid, lunsj og kjøring regnes ut":"Overtime, lunch and mileage calculated","Lønnsgrunnlag rett til lønnssystemet":"Payroll data straight to the payroll system","Prosjekter":"Projects","Adresse med kart, kontaktperson, selger, snekker og timer brukt mot kalkyle på hvert prosjekt.":"Address with map, contact person, salesperson, carpenter, and hours used versus estimate on every project.","Hentes fra Visma eller Tripletex":"Imported from Visma or Tripletex","Søk på nummer, kunde eller adresse":"Search by number, customer or address","Slå sammen to prosjekter som er samme jobb":"Merge two projects that are the same job","Arbeidsplan":"Work plan","Leder deler ut jobber med dato til de ansatte. Ukeplanen viser hvem som er hvor, og hvem som har ferie.":"Managers assign dated jobs to employees. The weekly plan shows who is where, and who is on holiday.","Trykk på en dag for å planlegge":"Tap a day to plan it","Bare hverdager – helg når det trengs":"Weekdays only – weekends when needed","«Mitt arbeid» for hver ansatt":"“My work” for each employee","Push-varsel når du får ny jobb":"Push notification when you get a new job","Materiell og bestilling":"Materials and ordering","Materiallisten deles i leveranser i riktig rekkefølge. Snekkeren bestiller fra byggeplassen, og butikken plukker.":"The material list is split into deliveries in the right order. The carpenter orders from the site, and the shop picks.","Leveranser med dato og status":"Deliveries with date and status","Bestilling rett til butikk og lager":"Orders straight to the shop and warehouse","Huk av det som er levert":"Tick off what’s been delivered","Egenkontroll og HMS":"Quality control and HSE","Sjekklister for våtrom, tetting, vinduer og brann som signeres på stedet, og sikker jobbanalyse før risikoarbeid.":"Checklists for wet rooms, sealing, windows and fire, signed on site, plus a safe job analysis before high-risk work.","SJA som alle kvitterer på":"SJA that everyone signs off on","Mannskapsliste med HMS-kort":"Crew list with HMS-kort","Avvik og uønskede hendelser":"Deviations and incidents","Dokumentasjon":"Documentation","Dagbok, bilder og tilleggsarbeid lagres på prosjektet mens jobben pågår. Kunden signerer tillegg på telefonen.":"Site diary, photos and extra work are saved to the project while the job is under way. The customer signs off extras on the phone.","Sluttrapport og FDV til kunden":"Final report and FDV for the customer","Klar for Boligmappa":"Ready for Boligmappa","Vær fra Meteorologisk institutt":"Weather from the Norwegian Meteorological Institute","Serviceoppdrag":"Service jobs","Små betalte jobber hos kunden som gjøres på en dag eller to. Merk hva som haster, del ut til en snekker og fakturer når det er gjort.":"Small paid jobs at the customer’s that take a day or two. Mark what’s urgent, assign it to a carpenter and invoice when it’s done.","Haster, denne uken eller når det passer":"Urgent, this week or whenever suits","Kunden bestiller selv via skjema på nettsiden":"Customers book themselves via a form on your website","Timer og materiell rett til «Klar til fakturering»":"Hours and materials straight to “Ready to invoice”","Kunden kvitterer på telefonen":"The customer signs off on the phone","Fire språk":"Four languages","Hver ansatt bruker appen på sitt eget språk: norsk, polsk, engelsk eller litauisk. Prosjekter, timer og chat er de samme for alle – det er bare knapper og tekster som byttes.":"Each employee uses the app in their own language: Norwegian, Polish, English or Lithuanian. Projects, hours and chat are the same for everyone – only the buttons and labels change.","Velg språk allerede på innloggingen":"Choose the language right at login","Invitasjonen kommer på den ansattes språk":"The invitation arrives in the employee’s language","Veiledning for iPhone og Android på alle språk":"Guides for iPhone and Android in every language","Reklamasjon":"Warranty claims","Når kunden melder feil på en ferdig jobb, registreres det på jobben med bilder. Leder vurderer, og utbedringen planlegges.":"When a customer reports a defect on a finished job, it’s logged on the job with photos. The manager assesses it, and the fix is scheduled.","Timer på reklamasjon faktureres ikke":"Hours on warranty claims are not invoiced","Kunden kvitterer når det er rettet":"The customer signs off when it’s fixed","Hva reklamasjoner koster i året":"What warranty claims cost per year","Tilleggsarbeid":"Extra work","Råteskade eller ekstraarbeid som dukker opp underveis blir et eget underprosjekt på jobben. Timene føres på tillegget, så du ser forbruket mot anslaget.":"Rot damage or extra work that turns up along the way becomes its own sub-project on the job. Hours are logged on the extra, so you see actual use against the estimate.","Kunden signerer på telefonen":"The customer signs on the phone","Snekkeren velger «Gjelder: tillegg» når han fører timer":"The carpenter picks “Applies to: extra” when logging hours","Faktureres for seg, også på fastprisjobber":"Invoiced separately, even on fixed-price jobs","Månedsrapport per ansatt":"Monthly report per employee","Hver ansatt får sin egen rapport. Snekkerne ser timer på kunde mot interntid, og butikk og prosjektleder ser dekningsgrad på salget sitt.":"Every employee gets their own report. Carpenters see customer hours versus internal time, and the shop and project managers see the margin on their sales.","Sammenlignet med forrige måned og snittet":"Compared with last month and the average","DG per varegruppe rett fra regnskapet":"Margin per product group straight from the accounts","Push-varsel når rapporten er klar":"Push notification when the report is ready","Salg per avdeling":"Sales per department","Egen rapport for hver avdeling, for eksempel kjøkken og interiør: antall salg, omsetning, dekningsbidrag og DG, hentet rett fra Visma.":"A separate report for each department, for example kitchen and interior: number of sales, revenue, contribution margin and margin %, pulled straight from Visma.","Per måned og hittil i år mot i fjor":"Per month and year to date versus last year","Ordre uten innkjøpspris vises for seg":"Orders without a cost price shown separately","Avdelingen ser sin egen rapport":"The department sees its own report","Egen logo og farger":"Your own logo and colours","Last opp logoen, så finner appen fargene i den og lager firmafarger. ByggLogg-merket står ved siden av.":"Upload your logo, and the app picks out its colours and creates company colours. The ByggLogg mark sits alongside.","Logo øverst i appen":"Logo at the top of the app","Logo og farger på sluttrapporten til kunden":"Logo and colours on the customer’s final report","Hver ansatt kan velge egne farger":"Each employee can choose their own colours","Ferie og fravær":"Holiday and absence","Søk ferie i appen og se felles feriekalender. Leder godkjenner med ett trykk.":"Request holiday in the app and see the shared holiday calendar. Managers approve with one tap.","Feriedager etter ferieloven":"Holiday entitlement under the Holidays Act","Egenmelding og sykt barn":"Self-certified sick leave and sick child","Kalender til mobilen":"Calendar on your phone","Chat og varsler":"Chat and notifications","Felles chat, egen tråd per prosjekt og private meldinger, med push-varsel på telefonen.":"Team chat, a separate thread per project and private messages, with push notifications on your phone.","Bilder rett i chatten":"Photos right in the chat","Varsel om nye prosjekter og bestillinger":"Alerts for new projects and orders","Hele appen på norsk, polsk, engelsk og litauisk":"The whole app in Norwegian, Polish, English and Lithuanian","Raskt i gang":"Quick to get started","Godkjenn ByggLogg i Visma, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Ansatte fra regnskapet legges til med ett trykk.":"Approve ByggLogg in Visma, or paste in the key from Tripletex, and your company connects automatically. Employees from the accounts are added with one tap.","Invitasjon på e-post på den ansattes eget språk":"Email invitation in the employee’s own language","Egen veiledning for iPhone og Android":"Dedicated guides for iPhone and Android","«Kom i gang»-liste som viser hva som gjenstår":"“Get started” checklist showing what’s left","Slik ser det ut":"See it in action","Bygget for telefonen. Like god på PC.":"Built for the phone. Just as good on a PC.","Snekkerne bruker ByggLogg på telefonen ute. Leder og butikk har den samme appen på PC, med ukeplan, bestillinger og reklamasjoner på én side.":"Carpenters use ByggLogg on their phones out on site. Managers and the shop use the same app on a PC, with the weekly plan, orders and warranty claims on one page.","Arbeidsplan.":"Work plan.","Hele uka for alle ansatte. Trykk på en ledig dag for å dele ut en jobb.":"The whole week for all employees. Tap a free day to assign a job.","Butikk og prosjektleder.":"Shop and project manager.","Bestillinger fra byggeplassen og reklamasjoner som skal følges opp.":"Orders from the site and warranty claims to follow up.","Alt om jobben på ett sted.":"Everything about the job in one place.","Plan, materiell, egenkontroll, bilder, avvik og sluttdokumentasjon på prosjektet.":"Plan, materials, quality control, photos, deviations and handover documentation on the project.","Regnskap og lønn":"Accounting and payroll","Ingen dobbeltføring":"No double entry","ByggLogg henter prosjekter og kunder automatisk fra regnskapssystemet dere allerede bruker. Det de ansatte registrerer ute, går tilbake som grunnlag for faktura og lønn.":"ByggLogg pulls projects and customers automatically from the accounting system you already use. What employees log in the field goes back as the basis for invoicing and payroll.","Visma Business NXT":"Visma Business NXT","Prosjekter, kunder, materiell og fakturerte timer":"Projects, customers, materials and invoiced hours","Tripletex":"Tripletex","Prosjekter, kunder og ansatte inn, godkjente timer og lønnsgrunnlag ut":"Projects, customers and employees in; approved hours and payroll data out","Visma Lønn":"Visma Lønn","Timer, overtid, kjøring, ferie og fravær som importfil":"Hours, overtime, mileage, holiday and absence as an import file","Prosjektet opprettes":"The project is created","Kontoret lager ordren i Visma, eller snekkeren oppretter prosjektet i appen når jobben starter før papirene er klare.":"The office creates the order in Visma, or the carpenter creates the project in the app when the job starts before the paperwork is ready.","Jobben gjøres":"The job gets done","Timer, bilder, avvik og materiell registreres på prosjektet. Prosjekter laget i appen kobles til prosjektet i regnskapet når det kommer.":"Hours, photos, deviations and materials are logged on the project. Projects made in the app are linked to the project in the accounts once it arrives.","Grunnlaget er klart":"The data is ready","Leder ser timer klare til fakturering, og sender lønnsgrunnlaget for måneden rett til Tripletex eller Visma Lønn – på bedriftens egne lønnsarter, uten å skrive noe av på nytt.":"Managers see hours ready to invoice, and send the month’s payroll data straight to Tripletex or Visma Lønn – using the company’s own pay codes, with nothing retyped.","Vi setter det opp for dere":"We set it up for you","Dere skal ikke trenge en IT-avdeling for å komme i gang. Vi gjør jobben, og dere får én person å ringe.":"You shouldn’t need an IT department to get started. We do the work, and you get one person to call.","Oppsett og import":"Setup and import","Vi legger inn ansatte, satser, regler for overtid og tillegg, og importerer prosjekter og kunder.":"We enter employees, rates, rules for overtime and allowances, and import projects and customers.","Kobling til regnskap":"Accounting integration","Godkjenn ByggLogg i Visma Business NXT, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Prosjekter, kunder og ansatte hentes inn, og timene går rett til lønn.":"Approve ByggLogg in Visma Business NXT, or paste in the key from Tripletex, and your company connects automatically. Projects, customers and employees are imported, and hours go straight to payroll.","Opplæring og invitasjon":"Training and invitations","De ansatte får invitasjon på e-post med innlogging og hvordan appen lagres på iPhone og Android. Kort gjennomgang på morgenmøtet, og en «Kom i gang»-liste for leder.":"Employees get an email invitation with their login and how to save the app on iPhone and Android. A short walkthrough at the morning meeting, and a “Get started” checklist for the manager.","Egen profil":"Your own branding","Firmanavn og logo i appen, i rapportene og i sluttdokumentasjonen dere sender kunden.":"Company name and logo in the app, in reports and in the handover documentation you send the customer.","Brukerstøtte":"Support","Svar på norsk fra folk som kjenner byggebransjen. Feil rettes fortløpende.":"Answers in Norwegian from people who know the construction industry. Bugs are fixed as they come up.","Videreutvikling":"Ongoing development","Nye funksjoner kommer jevnlig, og mange av dem starter som ønsker fra kundene.":"New features arrive regularly, and many of them start as customer requests.","Tilpass ByggLogg":"Tailor ByggLogg","Satt opp etter hvordan dere jobber":"Set up around how you work","Hver bedrift er forskjellig. Det meste stilles inn av leder i appen, og resten hjelper vi dere med.":"Every company is different. Most things are set by the manager in the app, and we help you with the rest.","Tilpasses per bedrift":"Tailored per company","Firmanavn, logo og farger i appen og i dokumentene til kunden":"Company name, logo and colours in the app and in customer documents","Avdelinger og hvor mange som kan ha ferie samtidig":"Departments and how many can be on holiday at once","Normaltid, lunsjtrekk og overtid per ansatt":"Normal hours, lunch deduction and overtime per employee","Feriedager etter avtale, med ekstra uke over 60 år":"Holiday days by agreement, with an extra week for over-60s","Varsel når noen har glemt å stemple ut, med egen grense per ansatt":"Alert when someone forgets to clock out, with a custom limit per employee","Kvoter for arbeidstøy, verktøy og verneutstyr":"Allowances for workwear, tools and safety equipment","Slå av deler av appen dere ikke bruker":"Switch off parts of the app you don’t use","Oversikt for leder: fakturerte timer mot mål, lønnsomhet, kurs og utstyr":"Manager overview: invoiced hours against target, profitability, courses and equipment","Prosjektleder-rolle for butikk og kontor":"Project manager role for shop and office","Personlig månedsrapport til hver ansatt, med det som er viktig i jobben deres":"Personal monthly report for each employee, with what matters in their job","Salgsrapport per avdeling, synlig for avdelingen selv":"Sales report per department, visible to the department itself","Fast serviceprosjekt og eget bestillingsskjema for kundene":"Standing service project and your own booking form for customers","Kampanjer fra kjeden på startsiden":"Campaigns from your chain on the home screen","Språk for hver ansatt: norsk, polsk, engelsk eller litauisk":"Language per employee: Norwegian, Polish, English or Lithuanian","Andre koblinger":"Other integrations","Kart og kjøreavstand til prosjektet fra Kartverket":"Map and driving distance to the project from the Norwegian Mapping Authority","Sluttdokumentasjon og FDV klar for Boligmappa":"Handover documentation and FDV ready for Boligmappa","Ferie og fravær rett i kalenderen på mobilen":"Holiday and absence straight into your phone’s calendar","Værmelding fra Meteorologisk institutt":"Weather forecast from the Norwegian Meteorological Institute","Push-varsler for chat, nye prosjekter, ny jobb, bestillinger, serviceoppdrag og månedsrapporten":"Push notifications for chat, new projects, new jobs, orders, service jobs and the monthly report","Invitasjon på e-post med egen veiledning for iPhone og Android":"Email invitation with dedicated guides for iPhone and Android","Import av timer fra Svenn ved bytte av system":"Import of hours from Svenn when switching systems","Trenger dere en kobling vi ikke har? Si fra. Mange av funksjonene i ByggLogg startet som ønsker fra kundene.":"Need an integration we don’t have? Let us know. Many of ByggLogg’s features started as customer requests.","Én pris per bruker":"One price per user","Dere betaler for de ansatte som bruker appen, måned for måned. Alle funksjoner er med.":"You pay for the employees who use the app, month by month. All features included.","kr per bruker / mnd":"NOK per user / month","eks. mva. · minst 5 brukere":"excl. VAT · minimum 5 users","Tillegg: kobling til Visma Business NXT eller Tripletex":"Add-on: integration with Visma Business NXT or Tripletex","kr per bedrift / mnd":"NOK per company / month","eks. mva. · 2 500 kr i oppstart":"excl. VAT · NOK 2 500 setup fee","Alle funksjoner":"All features","Nye versjoner":"New versions","Personvern og sikkerhet":"Privacy and security","Trygt for de ansatte":"Safe for your employees","ByggLogg følger personvernforordningen (GDPR) og arbeidsmiljølovens krav til oversikt over arbeidstid. Vi inngår databehandleravtale med alle kunder.":"ByggLogg complies with the GDPR and the Norwegian Working Environment Act’s requirements for recording working hours. We sign a data processing agreement with every customer.","Les avtalevilkårene":"Read the terms","Lagring":"Storage","Alle opplysninger lagres i EU (Irland).":"All data is stored in the EU (Ireland).","Posisjon":"Location","Appen sporer ikke hvor de ansatte er.":"The app does not track where employees are.","Sykefravær":"Sick leave","Bare typen fravær registreres, aldri diagnose.":"Only the type of absence is recorded, never a diagnosis.","Uten nett":"Offline","Det som er hentet, ligger på telefonen til den ansatte logger ut.":"Data already loaded stays on the phone until the employee logs out.","Innlogging":"Login","Engangskode på e-post. Ingen passord å glemme.":"One-time code by email. No password to forget.","Tilgang":"Access","Ansatte ser sine egne tall. Private meldinger kan bare leses av de to som skriver.":"Employees see their own figures. Private messages can only be read by the two people in the conversation.","Kom i gang":"Get started","Se ByggLogg i bruk":"See ByggLogg in use","Prøv demoen selv, eller ta kontakt for en gjennomgang. Vi viser gjerne hvordan appen brukes på en vanlig arbeidsdag.":"Try the demo yourself, or get in touch for a walkthrough. We’re happy to show how the app is used on an ordinary working day.","Ståle Jonassen":"Ståle Jonassen","Jonassen AS":"Jonassen AS","Lepsøyvegen 210, 6292 Kjerstad":"Lepsøyvegen 210, 6292 Kjerstad","post@bygglogg.app":"post@bygglogg.app","Kopier e-postadresse":"Copy email address","ByggLogg er et varemerke fra Jonassen AS · Lepsøyvegen 210, 6292 Kjerstad · org.nr. 919 665 319":"ByggLogg is a trademark of Jonassen AS · Lepsøyvegen 210, 6292 Kjerstad · org.nr. 919 665 319","Avtalevilkår":"Terms","Personvern":"Privacy","Hovedmeny":"Main menu","Skjermbilde av ByggLogg på telefon":"Screenshot of ByggLogg on a phone","Forsiden i ByggLogg: snekkeren er logget inn på prosjektet Skifte vindu og ser timene sine for dagen":"The ByggLogg home screen: the carpenter is clocked in on the project Skifte vindu and sees today’s hours","Ukeplanen i ByggLogg med jobber fordelt på de ansatte":"The weekly plan in ByggLogg with jobs assigned to employees","Bestillinger fra byggeplassen og reklamasjoner i ByggLogg":"Orders from the site and warranty claims in ByggLogg","Delene av et prosjekt i ByggLogg: plan, materiell, egenkontroll, SJA, chat, dagbok og mer":"The parts of a project in ByggLogg: plan, materials, quality control, SJA, chat, site diary and more","ByggLogg er appen for byggefirma: stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat – koblet til Visma Business NXT og Tripletex.":"ByggLogg is the app for construction firms: clocking in, hours, work plan, materials, quality control, warranty claims, holiday and chat – connected to Visma Business NXT and Tripletex.","Kopiert":"Copied","Merket – trykk Kopier":"Selected – press Copy"},"lt":{"ByggLogg":"ByggLogg","Funksjoner":"Funkcijos","Se appen":"Peržiūrėti programėlę","Tjenester":"Paslaugos","Pris":"Kaina","Kontakt":"Kontaktai","For byggefirma og håndverkere":"Statybos įmonėms ir meistrams","Hele byggeplassen":"Visa statybvietė","i lomma.":"jūsų kišenėje.","ByggLogg samler stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat i én app på telefonen. Prosjektene kommer rett fra Visma Business NXT eller Tripletex, og lønnsgrunnlaget er klart når måneden er slutt.":"ByggLogg vienoje telefono programėlėje sujungia darbo laiko žymėjimą, valandas, darbų planą, medžiagas, savikontrolę, reklamacijas, atostogas ir pokalbius. Projektai ateina tiesiai iš Visma Business NXT arba Tripletex, o atlyginimų duomenys paruošti vos pasibaigus mėnesiui.","Prøv demoen →":"Išbandykite demo versiją →","Snakk med oss":"Pasikalbėkite su mumis","Norsk, polsk, engelsk og litauisk":"Norvegų, lenkų, anglų ir lietuvių kalbomis","Ingen app-butikk":"Be programėlių parduotuvės","Data lagret i EU":"Duomenys saugomi ES","Hva ByggLogg gjør":"Ką daro ByggLogg","Laget på en byggevarehandel. Brukt hver dag av snekkerne.":"Sukurta statybinių prekių parduotuvėje. Dailidžių naudojama kasdien.","ByggLogg er utviklet ute i bransjen, sammen med snekkere som bruker appen hver dag, for å bli kvitt lapper, SMS-er og regneark. Alt de ansatte trenger på jobb ligger i én app, og leder får oversikten uten å ringe rundt.":"ByggLogg sukurta pačioje šakoje, kartu su dailidėmis, kurie programėlę naudoja kasdien – kad atsikratytume lapelių, SMS žinučių ir skaičiuoklių. Viskas, ko darbuotojams reikia darbe, yra vienoje programėlėje, o vadovas mato visą vaizdą, nereikėdamas visiems skambinėti.","Stempling og timer":"Darbo laiko žymėjimas ir valandos","Logg inn og ut med ett trykk, på riktig prosjekt. Dagen vises som et målebånd, så hullene synes.":"Pradėkite ir baigkite darbą vienu paspaudimu, tinkamame projekte. Diena rodoma kaip matavimo juosta, todėl spragos iškart matomos.","Virker uten nett – sendes når dekningen er tilbake":"Veikia be interneto – duomenys išsiunčiami, kai ryšys grįžta","Nyhet":"Naujiena","Varsel hvis noen har glemt å logge ut":"Pranešimas, jei kas nors pamiršo pažymėti darbo pabaigą","Overtid, lunsj og kjøring regnes ut":"Viršvalandžiai, pietų pertrauka ir kelionės apskaičiuojami automatiškai","Lønnsgrunnlag rett til lønnssystemet":"Atlyginimų duomenys tiesiai į darbo užmokesčio sistemą","Prosjekter":"Projektai","Adresse med kart, kontaktperson, selger, snekker og timer brukt mot kalkyle på hvert prosjekt.":"Kiekviename projekte – adresas su žemėlapiu, kontaktinis asmuo, pardavėjas, dailidė ir sunaudotos valandos, palygintos su sąmata.","Hentes fra Visma eller Tripletex":"Gaunami iš Visma arba Tripletex","Søk på nummer, kunde eller adresse":"Paieška pagal numerį, klientą arba adresą","Slå sammen to prosjekter som er samme jobb":"Sujunkite du projektus, kurie yra tas pats darbas","Arbeidsplan":"Darbų planas","Leder deler ut jobber med dato til de ansatte. Ukeplanen viser hvem som er hvor, og hvem som har ferie.":"Vadovas paskirsto darbuotojams darbus su datomis. Savaitės plane matyti, kas kur dirba ir kas atostogauja.","Trykk på en dag for å planlegge":"Paspauskite dieną, kad suplanuotumėte","Bare hverdager – helg når det trengs":"Tik darbo dienos – savaitgaliai, kai reikia","«Mitt arbeid» for hver ansatt":"„Mano darbai“ kiekvienam darbuotojui","Push-varsel når du får ny jobb":"Push pranešimas, kai gaunate naują darbą","Materiell og bestilling":"Medžiagos ir užsakymai","Materiallisten deles i leveranser i riktig rekkefølge. Snekkeren bestiller fra byggeplassen, og butikken plukker.":"Medžiagų sąrašas suskirstomas į pristatymus tinkama tvarka. Dailidė užsako tiesiai iš statybvietės, o parduotuvė surenka prekes.","Leveranser med dato og status":"Pristatymai su datomis ir būsena","Bestilling rett til butikk og lager":"Užsakymas tiesiai į parduotuvę ir sandėlį","Huk av det som er levert":"Pažymėkite, kas jau pristatyta","Egenkontroll og HMS":"Savikontrolė ir darbų sauga (HMS)","Sjekklister for våtrom, tetting, vinduer og brann som signeres på stedet, og sikker jobbanalyse før risikoarbeid.":"Šlapių patalpų, sandarinimo, langų ir priešgaisrinės saugos kontroliniai sąrašai, pasirašomi vietoje, ir saugaus darbo analizė prieš rizikingus darbus.","SJA som alle kvitterer på":"SJA, kurią patvirtina visi","Mannskapsliste med HMS-kort":"Darbuotojų sąrašas su HMS-kort","Avvik og uønskede hendelser":"Neatitiktys ir nepageidaujami įvykiai","Dokumentasjon":"Dokumentacija","Dagbok, bilder og tilleggsarbeid lagres på prosjektet mens jobben pågår. Kunden signerer tillegg på telefonen.":"Dienynas, nuotraukos ir papildomi darbai saugomi projekte, kol vyksta darbai. Klientas papildomus darbus pasirašo telefone.","Sluttrapport og FDV til kunden":"Baigiamoji ataskaita ir FDV klientui","Klar for Boligmappa":"Paruošta Boligmappa","Vær fra Meteorologisk institutt":"Orai iš Norvegijos meteorologijos instituto","Serviceoppdrag":"Serviso užsakymai","Små betalte jobber hos kunden som gjøres på en dag eller to. Merk hva som haster, del ut til en snekker og fakturer når det er gjort.":"Nedideli mokami darbai pas klientą, atliekami per dieną ar dvi. Pažymėkite, kas skubu, paskirkite dailidei ir išrašykite sąskaitą, kai darbas atliktas.","Haster, denne uken eller når det passer":"Skubu, šią savaitę arba kai patogu","Kunden bestiller selv via skjema på nettsiden":"Klientas pats užsako per formą svetainėje","Timer og materiell rett til «Klar til fakturering»":"Valandos ir medžiagos tiesiai į „Paruošta sąskaitai“","Kunden kvitterer på telefonen":"Klientas patvirtina telefone","Fire språk":"Keturios kalbos","Hver ansatt bruker appen på sitt eget språk: norsk, polsk, engelsk eller litauisk. Prosjekter, timer og chat er de samme for alle – det er bare knapper og tekster som byttes.":"Kiekvienas darbuotojas naudoja programėlę savo kalba: norvegų, lenkų, anglų arba lietuvių. Projektai, valandos ir pokalbiai visiems tie patys – keičiasi tik mygtukai ir tekstai.","Velg språk allerede på innloggingen":"Pasirinkite kalbą jau prisijungdami","Invitasjonen kommer på den ansattes språk":"Kvietimas ateina darbuotojo kalba","Veiledning for iPhone og Android på alle språk":"Instrukcijos iPhone ir Android visomis kalbomis","Reklamasjon":"Reklamacijos","Når kunden melder feil på en ferdig jobb, registreres det på jobben med bilder. Leder vurderer, og utbedringen planlegges.":"Kai klientas praneša apie defektą baigtame darbe, jis užregistruojamas prie darbo su nuotraukomis. Vadovas įvertina, ir ištaisymas suplanuojamas.","Timer på reklamasjon faktureres ikke":"Reklamacijų valandos nėra įtraukiamos į sąskaitą","Kunden kvitterer når det er rettet":"Klientas patvirtina, kai defektas ištaisytas","Hva reklamasjoner koster i året":"Kiek reklamacijos kainuoja per metus","Tilleggsarbeid":"Papildomi darbai","Råteskade eller ekstraarbeid som dukker opp underveis blir et eget underprosjekt på jobben. Timene føres på tillegget, så du ser forbruket mot anslaget.":"Puvinio pažeidimai ar papildomi darbai, išaiškėję eigoje, tampa atskiru darbo poprojekčiu. Valandos registruojamos papildomam darbui, todėl matote sąnaudas, palyginti su įvertinimu.","Kunden signerer på telefonen":"Klientas pasirašo telefone","Snekkeren velger «Gjelder: tillegg» når han fører timer":"Registruodamas valandas dailidė pasirenka „Taikoma: papildomas darbas“","Faktureres for seg, også på fastprisjobber":"Sąskaita išrašoma atskirai, net ir fiksuotos kainos darbuose","Månedsrapport per ansatt":"Mėnesio ataskaita kiekvienam darbuotojui","Hver ansatt får sin egen rapport. Snekkerne ser timer på kunde mot interntid, og butikk og prosjektleder ser dekningsgrad på salget sitt.":"Kiekvienas darbuotojas gauna savo ataskaitą. Dailidės mato klientui dirbtas valandas, palygintas su vidiniu laiku, o parduotuvė ir projektų vadovas – savo pardavimų maržą.","Sammenlignet med forrige måned og snittet":"Palyginti su praėjusiu mėnesiu ir vidurkiu","DG per varegruppe rett fra regnskapet":"Marža pagal prekių grupę tiesiai iš apskaitos","Push-varsel når rapporten er klar":"Push pranešimas, kai ataskaita paruošta","Salg per avdeling":"Pardavimai pagal skyrių","Egen rapport for hver avdeling, for eksempel kjøkken og interiør: antall salg, omsetning, dekningsbidrag og DG, hentet rett fra Visma.":"Atskira ataskaita kiekvienam skyriui, pavyzdžiui, virtuvių ir interjero: pardavimų skaičius, apyvarta, maržos įnašas ir marža procentais, gauti tiesiai iš Visma.","Per måned og hittil i år mot i fjor":"Pagal mėnesį ir nuo metų pradžios, palyginti su praėjusiais metais","Ordre uten innkjøpspris vises for seg":"Užsakymai be pirkimo kainos rodomi atskirai","Avdelingen ser sin egen rapport":"Skyrius mato savo ataskaitą","Egen logo og farger":"Jūsų logotipas ir spalvos","Last opp logoen, så finner appen fargene i den og lager firmafarger. ByggLogg-merket står ved siden av.":"Įkelkite logotipą – programėlė pati atpažins jo spalvas ir sukurs įmonės spalvų schemą. Šalia rodomas ByggLogg ženklas.","Logo øverst i appen":"Logotipas programėlės viršuje","Logo og farger på sluttrapporten til kunden":"Logotipas ir spalvos baigiamojoje ataskaitoje klientui","Hver ansatt kan velge egne farger":"Kiekvienas darbuotojas gali pasirinkti savo spalvas","Ferie og fravær":"Atostogos ir nebuvimas darbe","Søk ferie i appen og se felles feriekalender. Leder godkjenner med ett trykk.":"Prašykite atostogų programėlėje ir matykite bendrą atostogų kalendorių. Vadovas patvirtina vienu paspaudimu.","Feriedager etter ferieloven":"Atostogų dienos pagal Norvegijos atostogų įstatymą","Egenmelding og sykt barn":"Savideklaracija ir vaiko liga","Kalender til mobilen":"Kalendorius jūsų telefone","Chat og varsler":"Pokalbiai ir pranešimai","Felles chat, egen tråd per prosjekt og private meldinger, med push-varsel på telefonen.":"Bendras pokalbis, atskira gija kiekvienam projektui ir asmeninės žinutės, su push pranešimais telefone.","Bilder rett i chatten":"Nuotraukos tiesiai pokalbyje","Varsel om nye prosjekter og bestillinger":"Pranešimai apie naujus projektus ir užsakymus","Hele appen på norsk, polsk, engelsk og litauisk":"Visa programėlė norvegų, lenkų, anglų ir lietuvių kalbomis","Raskt i gang":"Greita pradžia","Godkjenn ByggLogg i Visma, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Ansatte fra regnskapet legges til med ett trykk.":"Patvirtinkite ByggLogg Visma sistemoje arba įklijuokite raktą iš Tripletex – ir įmonė prijungiama automatiškai. Darbuotojai iš apskaitos pridedami vienu paspaudimu.","Invitasjon på e-post på den ansattes eget språk":"Kvietimas el. paštu darbuotojo kalba","Egen veiledning for iPhone og Android":"Atskiros instrukcijos iPhone ir Android","«Kom i gang»-liste som viser hva som gjenstår":"Sąrašas „Pradėkite“, rodantis, kas dar liko","Slik ser det ut":"Kaip tai atrodo","Bygget for telefonen. Like god på PC.":"Sukurta telefonui. Puikiai veikia ir kompiuteryje.","Snekkerne bruker ByggLogg på telefonen ute. Leder og butikk har den samme appen på PC, med ukeplan, bestillinger og reklamasjoner på én side.":"Dailidės ByggLogg naudoja telefone lauke. Vadovas ir parduotuvė turi tą pačią programėlę kompiuteryje, su savaitės planu, užsakymais ir reklamacijomis viename puslapyje.","Arbeidsplan.":"Darbų planas.","Hele uka for alle ansatte. Trykk på en ledig dag for å dele ut en jobb.":"Visa savaitė visiems darbuotojams. Paspauskite laisvą dieną, kad paskirtumėte darbą.","Butikk og prosjektleder.":"Parduotuvė ir projektų vadovas.","Bestillinger fra byggeplassen og reklamasjoner som skal følges opp.":"Užsakymai iš statybviečių ir reklamacijos, kurias reikia sekti.","Alt om jobben på ett sted.":"Viskas apie darbą vienoje vietoje.","Plan, materiell, egenkontroll, bilder, avvik og sluttdokumentasjon på prosjektet.":"Planas, medžiagos, savikontrolė, nuotraukos, neatitiktys ir baigiamoji dokumentacija projekte.","Regnskap og lønn":"Apskaita ir atlyginimai","Ingen dobbeltføring":"Jokio dvigubo įvedimo","ByggLogg henter prosjekter og kunder automatisk fra regnskapssystemet dere allerede bruker. Det de ansatte registrerer ute, går tilbake som grunnlag for faktura og lønn.":"ByggLogg automatiškai gauna projektus ir klientus iš apskaitos sistemos, kurią jau naudojate. Tai, ką darbuotojai užregistruoja vietoje, grįžta kaip pagrindas sąskaitoms ir atlyginimams.","Visma Business NXT":"Visma Business NXT","Prosjekter, kunder, materiell og fakturerte timer":"Projektai, klientai, medžiagos ir apmokėtos valandos","Tripletex":"Tripletex","Prosjekter, kunder og ansatte inn, godkjente timer og lønnsgrunnlag ut":"Projektai, klientai ir darbuotojai – į sistemą, patvirtintos valandos ir atlyginimų duomenys – iš jos","Visma Lønn":"Visma Lønn","Timer, overtid, kjøring, ferie og fravær som importfil":"Valandos, viršvalandžiai, kelionės, atostogos ir nebuvimas darbe kaip importo failas","Prosjektet opprettes":"Sukuriamas projektas","Kontoret lager ordren i Visma, eller snekkeren oppretter prosjektet i appen når jobben starter før papirene er klare.":"Biuras sukuria užsakymą Visma sistemoje, arba dailidė sukuria projektą programėlėje, kai darbas prasideda dar prieš sutvarkant dokumentus.","Jobben gjøres":"Atliekamas darbas","Timer, bilder, avvik og materiell registreres på prosjektet. Prosjekter laget i appen kobles til prosjektet i regnskapet når det kommer.":"Valandos, nuotraukos, neatitiktys ir medžiagos registruojamos projekte. Programėlėje sukurti projektai susiejami su projektu apskaitoje, kai jis atsiranda.","Grunnlaget er klart":"Duomenys paruošti","Leder ser timer klare til fakturering, og sender lønnsgrunnlaget for måneden rett til Tripletex eller Visma Lønn – på bedriftens egne lønnsarter, uten å skrive noe av på nytt.":"Vadovas mato valandas, paruoštas sąskaitoms, ir išsiunčia mėnesio atlyginimų duomenis tiesiai į Tripletex arba Visma Lønn – pagal įmonės darbo užmokesčio rūšis, nieko neperrašinėjant iš naujo.","Vi setter det opp for dere":"Mes viską sutvarkysime už jus","Dere skal ikke trenge en IT-avdeling for å komme i gang. Vi gjør jobben, og dere får én person å ringe.":"Kad pradėtumėte, jums nereikės IT skyriaus. Darbą atliekame mes, o jūs turite vieną žmogų, kuriam galite paskambinti.","Oppsett og import":"Nustatymas ir importas","Vi legger inn ansatte, satser, regler for overtid og tillegg, og importerer prosjekter og kunder.":"Įvedame darbuotojus, įkainius, viršvalandžių ir priedų taisykles bei importuojame projektus ir klientus.","Kobling til regnskap":"Sujungimas su apskaita","Godkjenn ByggLogg i Visma Business NXT, eller lim inn nøkkelen fra Tripletex, så kobles firmaet av seg selv. Prosjekter, kunder og ansatte hentes inn, og timene går rett til lønn.":"Patvirtinkite ByggLogg Visma Business NXT sistemoje arba įklijuokite raktą iš Tripletex – ir įmonė prijungiama automatiškai. Projektai, klientai ir darbuotojai perkeliami, o valandos keliauja tiesiai į atlyginimus.","Opplæring og invitasjon":"Mokymai ir kvietimai","De ansatte får invitasjon på e-post med innlogging og hvordan appen lagres på iPhone og Android. Kort gjennomgang på morgenmøtet, og en «Kom i gang»-liste for leder.":"Darbuotojai gauna kvietimą el. paštu su prisijungimu ir instrukcija, kaip įsidiegti programėlę iPhone ir Android. Trumpa apžvalga rytiniame susirinkime ir sąrašas „Pradėkite“ vadovui.","Egen profil":"Jūsų įmonės profilis","Firmanavn og logo i appen, i rapportene og i sluttdokumentasjonen dere sender kunden.":"Įmonės pavadinimas ir logotipas programėlėje, ataskaitose ir baigiamojoje dokumentacijoje, kurią siunčiate klientui.","Brukerstøtte":"Klientų aptarnavimas","Svar på norsk fra folk som kjenner byggebransjen. Feil rettes fortløpende.":"Atsakymai norvegiškai iš žmonių, kurie išmano statybų šaką. Klaidos taisomos nuolat.","Videreutvikling":"Tolesnis tobulinimas","Nye funksjoner kommer jevnlig, og mange av dem starter som ønsker fra kundene.":"Naujos funkcijos atsiranda reguliariai, ir daugelis jų gimsta iš klientų pageidavimų.","Tilpass ByggLogg":"Pritaikykite ByggLogg","Satt opp etter hvordan dere jobber":"Nustatyta pagal tai, kaip dirbate jūs","Hver bedrift er forskjellig. Det meste stilles inn av leder i appen, og resten hjelper vi dere med.":"Kiekviena įmonė skirtinga. Daugumą dalykų vadovas nustato programėlėje, o su likusiais mes jums padėsime.","Tilpasses per bedrift":"Pritaikoma kiekvienai įmonei","Firmanavn, logo og farger i appen og i dokumentene til kunden":"Įmonės pavadinimas, logotipas ir spalvos programėlėje ir dokumentuose klientui","Avdelinger og hvor mange som kan ha ferie samtidig":"Skyriai ir kiek žmonių vienu metu gali atostogauti","Normaltid, lunsjtrekk og overtid per ansatt":"Įprastas darbo laikas, pietų pertraukos atskaitymas ir viršvalandžiai kiekvienam darbuotojui","Feriedager etter avtale, med ekstra uke over 60 år":"Atostogų dienos pagal susitarimą, su papildoma savaite vyresniems nei 60 metų","Varsel når noen har glemt å stemple ut, med egen grense per ansatt":"Pranešimas, kai kas nors pamiršo pažymėti darbo pabaigą, su atskira riba kiekvienam darbuotojui","Kvoter for arbeidstøy, verktøy og verneutstyr":"Darbo drabužių, įrankių ir apsaugos priemonių kvotos","Slå av deler av appen dere ikke bruker":"Išjunkite programėlės dalis, kurių nenaudojate","Oversikt for leder: fakturerte timer mot mål, lønnsomhet, kurs og utstyr":"Apžvalga vadovui: apmokėtos valandos palyginti su tikslu, pelningumas, kursai ir įranga","Prosjektleder-rolle for butikk og kontor":"Projektų vadovo vaidmuo parduotuvei ir biurui","Personlig månedsrapport til hver ansatt, med det som er viktig i jobben deres":"Asmeninė mėnesio ataskaita kiekvienam darbuotojui su tuo, kas svarbu jo darbe","Salgsrapport per avdeling, synlig for avdelingen selv":"Pardavimų ataskaita pagal skyrių, matoma pačiam skyriui","Fast serviceprosjekt og eget bestillingsskjema for kundene":"Nuolatinis serviso projektas ir atskira užsakymo forma klientams","Kampanjer fra kjeden på startsiden":"Tinklo akcijos pradiniame puslapyje","Språk for hver ansatt: norsk, polsk, engelsk eller litauisk":"Kalba kiekvienam darbuotojui: norvegų, lenkų, anglų arba lietuvių","Andre koblinger":"Kitos integracijos","Kart og kjøreavstand til prosjektet fra Kartverket":"Žemėlapis ir atstumas iki projekto iš Kartverket","Sluttdokumentasjon og FDV klar for Boligmappa":"Baigiamoji dokumentacija ir FDV, paruošta Boligmappa","Ferie og fravær rett i kalenderen på mobilen":"Atostogos ir nebuvimas darbe tiesiai telefono kalendoriuje","Værmelding fra Meteorologisk institutt":"Orų prognozė iš Norvegijos meteorologijos instituto","Push-varsler for chat, nye prosjekter, ny jobb, bestillinger, serviceoppdrag og månedsrapporten":"Push pranešimai apie pokalbius, naujus projektus, naujus darbus, užsakymus, serviso užsakymus ir mėnesio ataskaitą","Invitasjon på e-post med egen veiledning for iPhone og Android":"Kvietimas el. paštu su atskira instrukcija iPhone ir Android","Import av timer fra Svenn ved bytte av system":"Valandų importas iš Svenn keičiant sistemą","Trenger dere en kobling vi ikke har? Si fra. Mange av funksjonene i ByggLogg startet som ønsker fra kundene.":"Reikia integracijos, kurios neturime? Praneškite. Daugelis ByggLogg funkcijų gimė iš klientų pageidavimų.","Én pris per bruker":"Viena kaina už naudotoją","Dere betaler for de ansatte som bruker appen, måned for måned. Alle funksjoner er med.":"Mokate už darbuotojus, kurie naudoja programėlę, kas mėnesį. Visos funkcijos įskaičiuotos.","kr per bruker / mnd":"kr už naudotoją / mėn.","eks. mva. · minst 5 brukere":"be PVM · ne mažiau kaip 5 naudotojai","Tillegg: kobling til Visma Business NXT eller Tripletex":"Priedas: sujungimas su Visma Business NXT arba Tripletex","kr per bedrift / mnd":"kr už įmonę / mėn.","eks. mva. · 2 500 kr i oppstart":"be PVM · 2 500 kr už pradžią","Alle funksjoner":"Visos funkcijos","Nye versjoner":"Naujos versijos","Personvern og sikkerhet":"Privatumas ir saugumas","Trygt for de ansatte":"Saugu darbuotojams","ByggLogg følger personvernforordningen (GDPR) og arbeidsmiljølovens krav til oversikt over arbeidstid. Vi inngår databehandleravtale med alle kunder.":"ByggLogg laikosi Bendrojo duomenų apsaugos reglamento (BDAR / GDPR) ir Norvegijos darbo aplinkos įstatymo reikalavimų dėl darbo laiko apskaitos. Su visais klientais sudarome duomenų tvarkymo sutartį.","Les avtalevilkårene":"Skaityti sutarties sąlygas","Lagring":"Saugojimas","Alle opplysninger lagres i EU (Irland).":"Visa informacija saugoma ES (Airijoje).","Posisjon":"Buvimo vieta","Appen sporer ikke hvor de ansatte er.":"Programėlė neseka, kur yra darbuotojai.","Sykefravær":"Nedarbingumas","Bare typen fravær registreres, aldri diagnose.":"Registruojamas tik nebuvimo darbe tipas, niekada ne diagnozė.","Uten nett":"Be interneto","Det som er hentet, ligger på telefonen til den ansatte logger ut.":"Tai, kas atsisiųsta, lieka telefone, kol darbuotojas atsijungia.","Innlogging":"Prisijungimas","Engangskode på e-post. Ingen passord å glemme.":"Vienkartinis kodas el. paštu. Jokių slaptažodžių, kuriuos galima pamiršti.","Tilgang":"Prieiga","Ansatte ser sine egne tall. Private meldinger kan bare leses av de to som skriver.":"Darbuotojai mato tik savo duomenis. Asmenines žinutes gali skaityti tik du susirašinėjantys asmenys.","Kom i gang":"Pradėkite","Se ByggLogg i bruk":"Pamatykite ByggLogg darbe","Prøv demoen selv, eller ta kontakt for en gjennomgang. Vi viser gjerne hvordan appen brukes på en vanlig arbeidsdag.":"Išbandykite demo versiją patys arba susisiekite su mumis dėl pristatymo. Mielai parodysime, kaip programėlė naudojama įprastą darbo dieną.","Ståle Jonassen":"Ståle Jonassen","Jonassen AS":"Jonassen AS","Lepsøyvegen 210, 6292 Kjerstad":"Lepsøyvegen 210, 6292 Kjerstad","post@bygglogg.app":"post@bygglogg.app","Kopier e-postadresse":"Kopijuoti el. pašto adresą","ByggLogg er et varemerke fra Jonassen AS · Lepsøyvegen 210, 6292 Kjerstad · org.nr. 919 665 319":"ByggLogg yra Jonassen AS prekės ženklas · Lepsøyvegen 210, 6292 Kjerstad · org.nr. 919 665 319","Avtalevilkår":"Sutarties sąlygos","Personvern":"Privatumas","Hovedmeny":"Pagrindinis meniu","Skjermbilde av ByggLogg på telefon":"ByggLogg ekrano vaizdas telefone","Forsiden i ByggLogg: snekkeren er logget inn på prosjektet Skifte vindu og ser timene sine for dagen":"ByggLogg pradinis puslapis: dailidė prisijungęs prie projekto „Lango keitimas“ ir mato savo šios dienos valandas","Ukeplanen i ByggLogg med jobber fordelt på de ansatte":"Savaitės planas ByggLogg su darbais, paskirstytais darbuotojams","Bestillinger fra byggeplassen og reklamasjoner i ByggLogg":"Užsakymai iš statybviečių ir reklamacijos ByggLogg","Delene av et prosjekt i ByggLogg: plan, materiell, egenkontroll, SJA, chat, dagbok og mer":"ByggLogg projekto dalys: planas, medžiagos, savikontrolė, SJA, pokalbiai, dienynas ir kt.","ByggLogg er appen for byggefirma: stempling, timer, arbeidsplan, materiell, egenkontroll, reklamasjon, ferie og chat – koblet til Visma Business NXT og Tripletex.":"ByggLogg – programėlė statybos įmonėms: darbo laiko žymėjimas, valandos, darbų planas, medžiagos, savikontrolė, reklamacijos, atostogos ir pokalbiai – sujungta su Visma Business NXT ir Tripletex.","Kopiert":"Nukopijuota","Merket – trykk Kopier":"Pažymėta – paspauskite „Kopijuoti“"}};
/* Språk på bygglogg.app: norsk i HTML-en, polsk/engelsk/litauisk fra ordboken under.
   Valget lagres som «sprak» – samme nøkkel som appen, så appen åpner på samme språk. */
(function () {
  var SPRAK = ["nb", "pl", "en", "lt"];
  var orig = new WeakMap();
  var navn = { nb: "Norsk", pl: "Polski", en: "English", lt: "Lietuvių" };
  var aktiv = "nb";
  function rens(v) { return v.replace(/\s+/g, " ").trim(); }
  function ord(v) { var o = ORDBOK[aktiv]; if (aktiv === "nb" || !o) return v; var k = rens(v); return o[k] || v; }
  window.hjemOversett = function (v) { return ord(v); };
  function bytt(v) { var k = rens(v); if (!k) return v; var u = ord(k); if (u === k) return v; var m = v.match(/^\s*/)[0], n = v.match(/\s*$/)[0]; return m + u + n; }
  function bruk(s) {
    aktiv = s; document.documentElement.lang = s === "nb" ? "nb" : s;
    var w = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (var n = w.nextNode(); n; n = w.nextNode()) {
      var e = n.parentElement; if (!e || e.closest("script,style,svg,[data-ikke-oversett]")) continue;
      if (!orig.has(n)) orig.set(n, n.nodeValue);
      n.nodeValue = s === "nb" ? orig.get(n) : bytt(orig.get(n));
    }
    var attr = ["alt", "aria-label", "title", "placeholder"];
    document.querySelectorAll("[alt],[aria-label],[title],[placeholder]").forEach(function (e) {
      if (e.closest("[data-ikke-oversett]")) return;
      attr.forEach(function (a) { if (!e.hasAttribute(a)) return; var d = "data-nb-" + a; if (!e.hasAttribute(d)) e.setAttribute(d, e.getAttribute(a)); var v = e.getAttribute(d); e.setAttribute(a, s === "nb" ? v : bytt(v)); });
    });
    if (!document.documentElement.hasAttribute("data-nb-title")) document.documentElement.setAttribute("data-nb-title", document.title);
    document.title = s === "nb" ? document.documentElement.getAttribute("data-nb-title") : bytt(document.documentElement.getAttribute("data-nb-title"));
    var md = document.querySelector('meta[name="description"]');
    if (md) { if (!md.hasAttribute("data-nb")) md.setAttribute("data-nb", md.content); md.content = s === "nb" ? md.getAttribute("data-nb") : bytt(md.getAttribute("data-nb")); }
    document.querySelectorAll("[data-sprak]").forEach(function (b) { b.setAttribute("aria-pressed", String(b.getAttribute("data-sprak") === s)); });
  }
  function velg(s) {
    if (SPRAK.indexOf(s) < 0) s = "nb";
    try { localStorage.setItem("sprak", s); } catch (e) { /* privat modus */ }
    try { var u = new URL(location.href); if (s === "nb") u.searchParams.delete("lang"); else u.searchParams.set("lang", s); history.replaceState(null, "", u); } catch (e) { /* gammel nettleser */ }
    bruk(s);
  }
  var start = "nb";
  try { var q = new URLSearchParams(location.search).get("lang"); if (SPRAK.indexOf(q) >= 0) start = q; else { var l = localStorage.getItem("sprak"); if (SPRAK.indexOf(l) >= 0) start = l; } } catch (e) { /* ingen lagring */ }
  document.querySelectorAll("[data-sprak]").forEach(function (b) { b.addEventListener("click", function () { velg(b.getAttribute("data-sprak")); }); });
  bruk(start);
  void navn;
})();
